file.content:
        canonical = _json_pointer_canonical(tokens)
        try:
            position = self.pointers.index(canonical)
        except ValueError as error:
            raise ValueError(
                f"pointer {canonical!r} is not covered by this index"
            ) from error
        _check_json_value(value)
        resolved.append((position, value))
    start, stop = self._range_bounds(start, stop)
    if not resolved:
        return tuple(range(start, stop))
    result: tuple[int, ...] | None = None
    for position, value in resolved:
        merged = _json_groups_find_all(self.groups[position], value)
        hits = tuple(index for index in merged if start <= index < stop)
        if result is None:
            result = hits
        else:
            result = _intersect_ascending_tuples(result, hits)
        if not result:
            break
    return tuple(() if result is None else result)

def _resolve_where_expression(self, expression: Any) -> tuple:
    """Validate a :meth:`find_where` expression and resolve pointers.

    Returns a parallel tree with every leaf pointer replaced by its
    position in ``self.pointers``. Validation is pre-order: a node's
    own errors are reported before its children's, and children are
    checked from left to right.
    """
    if not isinstance(expression, tuple):
        raise TypeError("expression nodes must be tuples")
    if not expression:
        raise ValueError("expression node must not be empty")
    operator = expression[0]
    if not isinstance(operator, str):
        raise TypeError("expression operator must be a string")
    if operator == "eq":
        if len(expression) != 3:
            raise ValueError('an "eq" node must have exactly three items')
        _, pointer, value = expression
        tokens = _parse_json_pointer(pointer)
        canonical = _json_pointer_canonical(tokens)
        try:
            position = self.pointers.index(canonical)
        except ValueError as error:
            raise ValueError(
                f"pointer {canonical!r} is not covered by this index"
            ) from error
        _check_json_value(value)
        return ("eq", position, value)
    if operator == "in":
        if len(expression) != 3:
            raise ValueError('an "in" node must have exactly three items')
        _, pointer, values = expression
        tokens = _parse_json_pointer(pointer)
        canonical = _json_pointer_canonical(tokens)
        try:
            position = self.pointers.index(canonical)
        except ValueError as error:
            raise ValueError(
                f"pointer {canonical!r} is not covered by this index"
            ) from error
        if not isinstance(values, tuple):
            raise TypeError('"in" values must be a tuple of scalars')
        for value in values:
            _check_json_value(value)
        return ("in", position, values)
    if operator in ("lt", "le", "gt", "ge"):
        if len(expression) != 3:
            raise ValueError(
                f'a "{operator}" node must have exactly three items'
            )
        _, pointer, threshold = expression
        tokens = _parse_json_pointer(pointer)
        canonical = _json_pointer_canonical(tokens)
        try:
            position = self.pointers.index(canonical)
        except ValueError as error:
            raise ValueError(
                f"pointer {canonical!r} is not covered by this index"
            ) from error
        _check_json_threshold(threshold)
        return (operator, position, threshold)
    if operator == "prefix":
        if len(expression) != 3:
            raise ValueError(
                'a "prefix" node must have exactly three items'
            )
        _, pointer, text = expression
        tokens = _parse_json_pointer(pointer)
        canonical = _json_pointer_canonical(tokens)
        try:
            position = self.pointers.index(canonical)
        except ValueError as error:
            raise ValueError(
                f"pointer {canonical!r} is not covered by this index"
            ) from error
        if not isinstance(text, str):
            raise TypeError("prefix text must be a string")
        return ("prefix", position, text)
    if operator == "exists":
        if len(expression) != 2:
            raise ValueError(
                'an "exists" node must have exactly two items'
            )
        _, pointer = expression
        tokens = _parse_json_pointer(pointer)
        canonical = _json_pointer_canonical(tokens)
        try:
            position = self.pointers.index(canonical)
        except ValueError as error:
            raise ValueError(
                f"pointer {canonical!r} is not covered by this index"
            ) from error
        return ("exists", position)
    if operator == "type":
        if len(expression) != 3:
            raise ValueError(
                'a "type" node must have exactly three items'
            )
        _, pointer, kind = expression
        tokens = _parse_json_pointer(pointer)
        canonical = _json_pointer_canonical(tokens)
        try:
            position = self.pointers.index(canonical)
        except ValueError as error:
            raise ValueError(
                f"pointer {canonical!r} is not covered by this index"
            ) from error
        if not isinstance(kind, str):
            raise TypeError("type kind must be a string")
        if kind not in _JSON_TYPE_KINDS:
            raise ValueError(f"unknown type kind {kind!r}")
        return ("type", position, kind)
    if operator == "contains":
        if len(expression) != 3:
            raise ValueError(
                'a "contains" node must have exactly three items'
            )
        _, pointer, value = expression
        tokens = _parse_json_pointer(pointer)
        canonical = _json_pointer_canonical(tokens)
        try:
            position = self.pointers.index(canonical)
        except ValueError as error:
            raise ValueError(
                f"pointer {canonical!r} is not covered by this index"
            ) from error
        _check_json_value(value)
        return ("contains", position, value)
    if operator in ("and", "or"):
        if len(expression) != 2:
            raise ValueError(
                f'an "{operator}" node must have exactly two items'
            )
        children = expression[1]
        if not isinstance(children, tuple):
            raise TypeError(f'"{operator}" children must be a tuple')
        return (
            operator,
            tuple(
                self._resolve_where_expression(child) for child in children
            ),
        )
    if operator == "not":
        if len(expression) != 2:
            raise ValueError('"not" node must have exactly two items')
        return ("not", self._resolve_where_expression(expression[1]))
    raise ValueError(f"unknown expression operator {operator!r}")

def _evaluate_where_expression(
    self, node: tuple, start: int, stop: int
) -> tuple[int, ...]:
    """Evaluate a resolved :meth:`find_where` tree over [start, stop)."""
    operator = node[0]
    if operator == "eq":
        merged = _json_groups_find_all(self.groups[node[1]], node[2])
        return tuple(index for index in merged if start <= index < stop)
    if operator == "in":
        merged = _union_ascending_tuples(
            tuple(
                _json_groups_find_all(self.groups[node[1]], value)
                for value in node[2]
            )
        )
        return tuple(index for index in merged if start <= index < stop)
    if operator in ("lt", "le", "gt", "ge"):
        merged = _json_groups_find_range(
            self.groups[node[1]], operator, node[2]
        )
        return tuple(index for index in merged if start <= index < stop)
    if operator == "prefix":
        merged = _json_groups_find_prefix(self.groups[node[1]], node[2])
        return tuple(index for index in merged if start <= index < stop)
    if operator == "exists":
        return self._exists_hits(node[1], start, stop)
    if operator == "type":
        return self._type_hits(node[1], node[2], start, stop)
    if operator == "contains":
        return self._contains_hits(node[1], node[2], start, stop)
    if operator == "and":
        children = node[1]
        if not children:
            return tuple(range(start, stop))
        result: tuple[int, ...] | None = None
        for child in children:
            hits = self._evaluate_where_expression(child, start, stop)
            if result is None:
                result = hits
            else:
                result = _intersect_ascending_tuples(result, hits)
            if not result:
                break
        return tuple(() if result is None else result)
    if operator == "or":
        return _union_ascending_tuples(
            tuple(
                self._evaluate_where_expression(child, start, stop)
                for child in node[1]
            )
        )
    # "not": complement over every index of the query range.
    hits = self._evaluate_where_expression(node[1], start, stop)
    return _complement_ascending_tuple(hits, start, stop)

def _exists_hits(self, position: int, start: int, stop: int) -> tuple[int, ...]:
    """Evaluate a resolved ``exists`` leaf over [start, stop).

    Walks the frozen covered entries in ascending order and reports
    every index whose payload is strict UTF-8 JSON (no repeated
    member name) in which the bound pointer resolves to any value —
    null, a scalar, an object or an array. An AES-256-GCM envelope
    and every parse failure simply do not hit; neither raises.
    """
    tokens = _parse_json_pointer(self.pointers[position])
    hits: list[int] = []
    for entry in self.items:
        if entry.index < start:
            continue
        if entry.index >= stop:
            break
        payload = entry.payload
        if payload.startswith(_ENC_MAGIC):
            # An AES-256-GCM envelope is never plain JSON; it takes
            # no part and never reaches the parser.
            continue
        document = _strict_json_document(payload)
        if document is _JSON_MISSING:
            continue
        if _json_pointer_exists(document, tokens):
            hits.append(entry.index)
    return tuple(hits)

def _type_hits(
    self, position: int, kind: str, start: int, stop: int
) -> tuple[int, ...]:
    """Evaluate a resolved ``type`` leaf over [start, stop).

    Walks the frozen covered entries in ascending order and reports
    every index whose payload is strict UTF-8 JSON (no repeated
    member name, no non-finite number) in which the bound pointer
    resolves to a value whose JSON type is ``kind`` — integers and
    finite floats are both "number", booleans are not numbers, and
    the empty array and empty object are "array" / "object". An
    AES-256-GCM envelope, every parse failure, a missing field, an
    invalid array position and a path through a scalar simply do not
    hit; neither raises.
    """
    tokens = _parse_json_pointer(self.pointers[position])
    hits: list[int] = []
    for entry in self.items:
        if entry.index < start:
            continue
        if entry.index >= stop:
            break
        payload = entry.payload
        if payload.startswith(_ENC_MAGIC):
            # An AES-256-GCM envelope is never plain JSON; it takes
            # no part and never reaches the parser.
            continue
        document = _strict_json_document(payload)
        if document is _JSON_MISSING:
            continue
        value = _json_pointer_value(document, tokens)
        if value is _JSON_MISSING:
            continue
        if _json_type_kind_of(value) == kind:
            hits.append(entry.index)
    return tuple(hits)

def _contains_hits(
    self, position: int, value: Any, start: int, stop: int
) -> tuple[int, ...]:
    """Evaluate a resolved ``contains`` leaf over [start, stop).

    Walks the frozen covered entries in ascending order and reports
    every index whose payload is strict UTF-8 JSON (no repeated
    member name, no non-finite number) in which the bound pointer
    resolves to an array carrying at least one direct element equal
    to ``value`` under the find_json scalar comparison — strings,
    booleans and null match only their own kind while ints and
    floats compare by numeric value. Repeated elements still
    produce a single hit, nested arrays and objects are never
    unfolded, and an empty array, a non-array target, a missing
    path, every parse failure and an AES-256-GCM envelope simply do
    not hit; none of them raises.
    """
    tokens = _parse_json_pointer(self.pointers[position])
    hits: list[int] = []
    for entry in self.items:
        if entry.index < start:
            continue
        if entry.index >= stop:
            break
        payload = entry.payload
        if payload.startswith(_ENC_MAGIC):
            # An AES-256-GCM envelope is never plain JSON; it takes
            # no part and never reaches the parser.
            continue
        document = _strict_json_document(payload)
        if document is _JSON_MISSING:
            continue
        target = _json_pointer_value(document, tokens)
        if not isinstance(target, list):
            continue
        for element in target:
            if _json_scalar_matches(element, value):
                hits.append(entry.index)
                break
    return tuple(hits)

def find_where(
    self,
    expression: Any,
    start: int | None = None,
    stop: int | None = None,
) -> tuple[int, ...]:
    """Answer a nested boolean query of find_json equality leaves.

    ``expression`` is a tuple tree. A leaf is ``("eq", pointer,
    value)`` and follows exactly the rules of :meth:`find`: the
    pointer must be a canonical RFC 6901 spelling bound by this index
    and ``value`` a JSON scalar (``str``, ``int``, finite ``float``,
    ``bool`` or ``None``) with the same kind-separated comparison —
    strings, booleans and null match only their own kind while ints
    and floats compare by numeric value. A set-membership leaf is
    ``("in", pointer, values)`` with the same pointer rules;
    ``values`` is a tuple of candidate scalars, each following
    exactly the ``eq`` value rules, and an entry matches when its
    addressed scalar equals any one candidate — repeated candidates
    never add duplicate hits and an empty candidate tuple matches
    nothing. A numeric-comparison leaf is
    ``("lt", pointer, threshold)``, ``("le", pointer, threshold)``,
    ``("gt", pointer, threshold)`` or ``("ge", pointer, threshold)``
    with the same pointer rules; ``threshold`` must be a non-boolean
    ``int`` or a finite ``float`` and the addressed JSON number
    compares against it by exact numeric value across the integer
    and float kinds — big integers never round to a nearby float and
    negative zero equals positive zero. A string-prefix leaf is
    ``("prefix", pointer, text)`` with the same pointer rules;
    ``text`` must be a ``str`` and only an addressed JSON string
    that starts with it matches — case-sensitively and without any
    Unicode normalization — so the empty prefix matches every
    string, the empty string included. A field-existence leaf is
    ``("exists", pointer)`` with the same pointer rules; it matches
    every entry whose payload is strict UTF-8 JSON (no repeated
    member name) in which the pointer resolves to any value at all
    — null, a scalar, an object or an array — so a missing field
    and a field explicitly set to ``null`` are told apart, the
    empty pointer matches every valid JSON document (the empty
    object and the empty array included), and an out-of-range,
    leading-zero or append-position array token or a path through a
    scalar does not hit. A value-type leaf is
    ``("type", pointer, kind)`` with the same pointer rules; ``kind``
    must be one of the case-sensitive strings ``"null"``,
    ``"boolean"``, ``"number"``, ``"string"``, ``"array"`` or
    ``"object"`` and matches every entry whose payload is strict
    UTF-8 JSON (no repeated member name, no non-finite number) in
    which the pointer resolves to a value of that JSON type —
    integers and finite floats are both ``"number"``, booleans are
    not numbers, and the empty array and empty object match
    ``"array"`` / ``"object"``; the empty pointer addresses the
    whole document, so it matches every valid JSON document of the
    named type. An array-membership leaf is
    ``("contains", pointer, value)`` with the same pointer rules and
    the same scalar ``value`` rules as ``eq``; it matches every
    entry whose payload is strict UTF-8 JSON (no repeated member
    name, no non-finite number) in which the pointer resolves to an
    array carrying at least one direct element equal to ``value``
    under the same kind-separated comparison — strings, booleans
    and null match only their own kind while ints and floats
    compare by numeric value. Repeated elements still yield a
    single hit, nested arrays and objects are never unfolded, and
    an empty array, a non-array target, a missing path, an invalid
    document and an encrypted entry never match; the empty pointer
    addresses the whole document, so it matches every valid JSON
    document that is itself an array containing ``value``. A
    combination is
    ``("and", children)``, ``("or", children)`` or ``("not", child)``
    where ``children`` is a tuple of sub-expressions that may nest
    recursively. ``and`` intersects its children's hits, ``or`` takes
    their union and ``not`` complements its child against every index
    of the query range. An empty ``and`` returns the whole range, an
    empty ``or`` returns ``()``, a double negation restores the
    original hits and repeating a branch never adds duplicate hits.
    The result is a tuple of absolute indices in strictly ascending
    order without duplicates (``()`` when nothing matches), clipped
    to the half-open ``[start, stop)`` range with the same defaults
    and bounds as :meth:`find`; an empty range yields ``()``.

    Non-JSON, encrypted, missing-field and non-scalar targets never
    satisfy an ``eq`` or ``in`` leaf — a missing field is not
    ``null`` — and
    non-numeric targets (booleans, strings, null, objects and arrays)
    never satisfy a numeric-comparison leaf, just as non-string
    targets never satisfy a ``prefix`` leaf, so all of them do
    satisfy that leaf's negation, exactly as for :meth:`find`.
    Invalid UTF-8, invalid JSON, a repeated member name and an
    encrypted entry never satisfy an ``exists`` or ``type`` leaf
    either — the parse failure is not a query error — so they
    satisfy its negation, exactly as a missing field, an invalid
    array position or a path through a scalar never satisfies a
    ``type`` leaf. A
    non-tuple node or ``children``, a non-string operator or pointer,
    a value or threshold of another type, a non-string prefix text,
    a non-string ``type`` kind,
    a non-tuple ``in`` candidate container or a candidate of another
    type,
    or a wrong-typed range bound raises TypeError; an empty node, an
    unknown operator, an unknown ``type`` kind name, a node of the
    wrong length, a malformed or
    uncovered pointer, a non-finite float value, threshold or ``in``
    candidate, or an
    out-of-range or reversed range raises ValueError. The whole expression is
    validated before any lookup — a node's own errors before its
    children's, children from left to right, an ``in`` node's length
    and pointer before its candidate container and each candidate in
    order, a ``type`` node's length before its pointer and its
    pointer before its kind, the range last — so an
    empty range, an empty candidate tuple or an already determined
    intermediate result never
    masks an invalid branch. The lookup is read-only and never
    mutates the index.
    """
    resolved = self._resolve_where_expression(expression)
    start, stop = self._range_bounds(start, stop)
    return self._evaluate_where_expression(resolved, start, stop)

    types and arbitrary-precision integers
    included — and re-encoding reproduces the original bytes exactly. A
    structurally sound receipt whose claim simply does not verify still
    decodes; :func:`verify_where_receipt` reports False. The call is
    read-only.
    """
    if not isinstance(data, bytes):
        raise TypeError("data must be bytes")
    if not data.startswith(_WHERE_RECEIPT_MAGIC):
        raise ValueError("not an auditchain where-receipt encoding")
    offset = len(_WHERE_RECEIPT_MAGIC)

    def read_u64(name: str) -> int:
        nonlocal offset
        end = offset + _U64_BYTES
        if end > len(data):
            raise ValueError(f"truncated encoding: expected 8 bytes for {name}")
        value = int.from_bytes(data[offset:end], "big")
        offset = end
        return value

    def read_blob(name: str) -> bytes:
        nonlocal offset
        length = read_u64(f"{name} length")
        end = offset + length
        if end > len(data):
            raise ValueError(f"truncated encoding: {name} is {length} bytes")
        blob = data[offset:end]
        offset = end
        return blob

    def read_expression(position: str) -> tuple:
        tag = read_u64(f"{position} tag")
        if tag == _WHERE_TAG_EXISTS:
            raw_pointer = read_blob(f"{position} pointer")
            try:
                pointer = raw_pointer.decode("utf-8")
            except UnicodeDecodeError as error:
                raise ValueError(
                    f"{position} pointer is not valid UTF-8"
                ) from error
            return ("exists", pointer)
        if tag == _WHERE_TAG_TYPE:
            raw_pointer = read_blob(f"{position} pointer")
            try:
                pointer = raw_pointer.decode("utf-8")
            except UnicodeDecodeError as error:
                raise ValueError(
                    f"{position} pointer is not valid UTF-8"
                ) from error
            raw_kind = read_blob(f"{position} kind")
            try:
                kind = raw_kind.decode("utf-8")
            except UnicodeDecodeError as error:
                raise ValueError(
                    f"{position} kind is not valid UTF-8"
                ) from error
            return ("type", pointer, kind)
        if tag == _WHERE_TAG_IN:
            raw_pointer = read_blob(f"{position} pointer")
            try:
                pointer = raw_pointer.decode("utf-8")
            except UnicodeDecodeError as error:
                raise ValueError(
                    f"{position} pointer is not valid UTF-8"
                ) from error
            value_count = read_u64(f"{position} values count")
            values: list[Any] = []
            for index in range(value_count):
                value_tag = read_u64(f"{position} value {index} tag")
                key = read_blob(f"{position} value {index}")
                values.append(_decode_json_condition_value(value_tag, key))
            return ("in", pointer, tuple(values))
        if tag in _WHERE_TAG_OPERATORS:
            operator = _WHERE_TAG_OPERATORS[tag]
            raw_pointer = read_blob(f"{position} pointer")
            try:
                pointer = raw_pointer.decode("utf-8")
            except UnicodeDecodeError as error:
                raise ValueError(
                    f"{position} pointer is not valid UTF-8"
                ) from error
            value_tag = read_u64(f"{position} value tag")
            key = read_blob(f"{position} value")
            if tag == _WHERE_TAG_PREFIX:
                if value_tag != _JSON_TAG_STRING:
                    raise ValueError(
                        'a "prefix" text must be a string'
                    )
            elif tag not in (_WHERE_TAG_EQ, _WHERE_TAG_CONTAINS) and (
                value_tag not in (
                    _JSON_TAG_INTEGER,
                    _JSON_TAG_FLOAT,
                )
            ):
                raise ValueError(
                    f'a "{operator}" threshold must be an integer or a float'
                )
            return (
                operator,
                pointer,
                _decode_json_condition_value(value_tag, key),
            )
        if tag == _WHERE_TAG_AND or tag == _WHERE_TAG_OR:
            operator = "and" if tag == _WHERE_TAG_AND else "or"
            child_count = read_u64(f"{position} children count")
            return (
                operator,
                tuple(
                    read_expression(f"{position} child {index}")
                    for index in range(child_count)
                ),
            )
        if tag == _WHERE_TAG_NOT:
            return ("not", read_expression(f"{position} child"))
        raise ValueError(f"unknown expression node tag {tag}")

    version = read_u64("version")
    if version != _WHERE_RECEIPT_VERSION:
        raise ValueError(f"unsupported where-receipt version {version}")
    bundle = decode_signed_json_multi_index(read_blob("bundle"))
    expression = read_expression("expression")
    start = read_u64("start")
    stop = read_u64("stop")
    hit_count = read_u64("hits count")
    hits = tuple(read_u64("hit") for _ in range(hit_count))
    if offset != len(data):
        raise ValueError("trailing bytes after the where receipt")
    return WhereReceipt(
        bundle=bundle,
        expression=expression,
        start=start,
        stop=stop,
        hits=hits,
    )


def encode_signed_where_receipt(bundle: Any) -> bytes:
    """Encode a :class:`SignedWhereReceipt` into canonical bytes.

    The encoding starts with the magic
    ``b"auditchain/signed-where-receipt/v1\\0"``; it then writes, strictly
    in order, the envelope ``version`` (always 1) as an unsigned 8-byte
    big-endian integer, the receipt blob and the raw 64-byte Ed25519
    signature — nothing may be omitted, reordered or appended. The receipt
    blob is a u64 byte length followed by the complete canonical output of
    :func:`encode_where_receipt` over ``bundle.receipt``; the signature
    follows verbatim. The signed message embeds exactly those receipt
    bytes, so no new signing message is introduced beyond the
    signed-where-receipt domain separator.

    ``bundle`` must be a :class:`SignedWhereReceipt` — anything else, or a
    bundle whose container fields have been bypassed to wrong types,
    raises TypeError; nested structural problems raise exactly the
    exceptions of :func:`encode_where_receipt` (TypeError or ValueError),
    and a signature that is not 64 bytes raises ValueError. Encoding is
    deterministic: re-encoding a decoded bundle reproduces the original
    bytes exactly, and a structurally valid bundle whose signature does
    not match encodes just as well.
    """
    if not isinstance(bundle, SignedWhereReceipt):
        raise TypeError("bundle must be a SignedWhereReceipt")
    # Re-validate the container even for an instance whose fields were set
    # bypassing the frozen constructor, so container-type corruption raises
    # TypeError exactly as the constructor would.
    checked = SignedWhereReceipt(bundle.receipt, bundle.signature)
    receipt_blob = encode_where_receipt(checked.receipt)
    return b"".join((
        _SIGNED_WHERE_RECEIPT_MAGIC,
        _encode_u64(_SIGNED_WHERE_RECEIPT_VERSION, "version"),
        _encode_blob(receipt_blob),
        checked.signature,
    ))


def decode_signed_where_receipt(data: Any) -> SignedWhereReceipt:
    """Decode bytes produced by :func:`encode_signed_where_receipt`.

    ``data`` must be exact ``bytes`` (anything else, including
    ``bytearray`` and ``memoryview``, raises TypeError). After the magic
    ``b"auditchain/signed-where-receipt/v1\\0"`` it must contain, strictly
    in order, the u64 envelope version (only ``1`` is supported), one
    length-prefixed receipt blob and exactly 64 raw signature bytes, with
    no trailing bytes. The receipt blob is handed whole to
    :func:`decode_where_receipt`, so every nested framing and structural
    rule is hers. A bad magic or version, truncation, an oversized blob
    length, trailing bytes, a signature that is not 64 bytes or an
    illegal nested encoding all raise ValueError.

    The returned object is a frozen :class:`SignedWhereReceipt` whose
    fields equal the originally encoded ones, and re-encoding reproduces
    the original bytes exactly. A structurally sound encoding whose
    signature simply does not verify still decodes;
    :func:`verify_signed_where_receipt` reports False. The call is
    read-only.
    """
    if not isinstance(data, bytes):
        raise TypeError("data must be bytes")
    if not data.startswith(_SIGNED_WHERE_RECEIPT_MAGIC):
        raise ValueError("not an auditchain signed-where-receipt encoding")
    offset = len(_SIGNED_WHERE_RECEIPT_MAGIC)

    def read_u64(name: str) -> int:
        nonlocal offset
        end = offset + _U64_BYTES
        if end > len(data):
            raise ValueError(f"truncated encoding: expected 8 bytes for {name}")
        value = int.from_bytes(data[offset:end], "big")
        offset = end
        return value

    def read_blob(name: str) -> bytes:
        nonlocal offset
        length = read_u64(f"{name} length")
        end = offset + length
        if end > len(data):
            raise ValueError(f"truncated encoding: {name} is {length} bytes")
        blob = data[offset:end]
        offset = end
        return blob

# Sentinel for "this payload yields no queryable scalar at the pointer".
_JSON_MISSING = object()

# Kind names accepted by the find_where "type" leaf, matched
# case-sensitively: integers and finite floats are both "number", booleans
# are not numbers, and the empty array/object are "array"/"object".
_JSON_TYPE_KINDS = frozenset(
    {"null", "boolean", "number", "string", "array", "object"}
)

# Scalar kinds that may appear in a JsonSearchIndex group.
_JSON_INDEX_KINDS = frozenset(
    {
        _JSON_TAG_STRING,
        _JSON_TAG_INTEGER,
        _JSON_TAG_FLOAT,
        _JSON_TAG_TRUE,
        _JSON_TAG_NULL,
        _JSON_TAG_FALSE,
    }
)

# Kinds whose single value is encoded as the empty blob (true / false / null).
_JSON_INDEX_EMPTY_KINDS = frozenset(
    {_JSON_TAG_TRUE, _JSON_TAG_FALSE, _JSON_TAG_NULL}
)


class _JsonDuplicateMember(ValueError):
    """Internal: a JSON object repeated a member name."""


def _decode_json_index_numeric(kind: int, key: bytes) -> Any:
    """Decode a canonical integer/float bucket key back to its number.

    Structural validity (ASCII, finite) is enforced by
    :func:`_check_json_index_bucket_key`; this only re-parses.
    """
    if kind == _JSON_TAG_INTEGER:
        return int(key.decode("ascii"))
    return float(key.decode("ascii"))


def _check_json_index_bucket_key(kind: int, key: Any) -> None:
    """Validate one bucket key blob for its group's kind."""
    if not isinstance(key, bytes):
        raise TypeError("bucket key must be bytes")
    if kind in _JSON_INDEX_EMPTY_KINDS:
        if key:
            raise ValueError(
                "a boolean or null bucket key must be the empty blob"
            )
        return
    if kind == _JSON_TAG_STRING:
        # Strings carry arbitrary text; the key must be valid UTF-8.
        try:
            key.decode("utf-8")
        except UnicodeDecodeError as error:
            raise ValueError("string bucket key must be valid UTF-8") from error
        return
    try:
        text = key.decode("ascii")
    except UnicodeDecodeError as error:
        raise ValueError("numeric bucket key must be ASCII") from error
    if kind == _JSON_TAG_INTEGER:
        digits = text[1:] if text[:1] == "-" else text
        if not digits or any(ch not in "0123456789" for ch in digits):
            raise ValueError("integer bucket key must be canonical ASCII decimal")
    elif kind == _JSON_TAG_FLOAT:
        try:
            value = float(text)
        except ValueError as error:
            raise ValueError("float bucket key must be an ASCII number") from error
        if not math.isfinite(value):
            raise ValueError("float bucket key must be finite")
        if repr(value).encode("ascii") != key:
            raise ValueError("float bucket key must be the canonical repr spelling")


def _check_json_value(value: Any) -> None:
    """Validate a find_json / json_search_receipt scalar query value."""
    if isinstance(value, bool) or isinstance(value, str) or value is None:
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("value must be a finite number")
        return
    raise TypeError("value must be str, int, float, bool or None")


def _check_json_threshold(value: Any) -> None:
    """Validate a find_where numeric-comparison threshold.

    Only a non-boolean ``int`` or a finite ``float`` is accepted: booleans
    are not numbers for this comparison, and a non-finite threshold would
    make the comparison degenerate.
    """
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("threshold must be an int or a float")
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError("threshold must be a finite number")


def _parse_json_pointer(pointer: Any) -> tuple[str, ...]:
    """Parse an RFC 6901 JSON Pointer into its tuple of unescaped tokens.

    The empty string is the root pointer and yields ``()``. A non-``str``
    pointer raises TypeError; a non-empty pointer that does not start with
    ``/`` or a reference token carrying an escape other than ``~0`` /
    ``~1`` raises ValueError.
    """
    if not isinstance(pointer, str):
        raise TypeError("pointer must be a string")
    if pointer == "":
        return ()
    if not pointer.startswith("/"):
        raise ValueError("a non-empty JSON Pointer must start with '/'")
    tokens: list[str] = []
    for raw in pointer.split("/")[1:]:
        if "~" not in raw:
            tokens.append(raw)
            continue
        decoded: list[str] = []
        index = 0
        while index < len(raw):
            char = raw[index]
            if char == "~":
                if index + 1 >= len(raw) or raw[index + 1] not in "01":
                    raise ValueError("JSON Pointer escape must be '~0' or '~1'")
                decoded.append("~" if raw[index + 1] == "0" else "/")
                index += 2
            else:
                decoded.append(char)
                index += 1
        tokens.append("".join(decoded))
    return tuple(tokens)


def _json_pointer_canonical(tokens: tuple[str, ...]) -> str:
    """Canonical RFC 6901 spelling of parsed pointer tokens."""
    if not tokens:
        return ""
    return "".join(
        "/" + token.replace("~", "~0").replace("/", "~1") for token in tokens
    )


def _json_reject_duplicates(pairs: Any) -> dict:
    document: dict = {}
    for key, value in pairs:
        if key in document:
            raise _JsonDuplicateMember(f"duplicate JSON object member {key!r}")
        document[key] = value
    return document


def _json_reject_constant(value: str) -> Any:
    # RFC 8259 has no NaN/Infinity; Python's json accepts them by default.
    raise ValueError(f"{value} is not valid JSON")


def _strict_json_document(payload: bytes) -> Any:
    """Decode and parse strict UTF-8 JSON bytes, or ``_JSON_MISSING``.

    A single strict parse shared by every pointer bound to the same
    payload: the bytes must decode as UTF-8 and parse as JSON with no
    repeated object member name at any depth and no non-finite number.
    Every failure mode (bad UTF-8, invalid JSON, a repeated member)
    counts as one parse attempt and yields the ``_JSON_MISSING``
    sentinel, exactly like :func:`_json_scalar_at`.
    """
    try:
        text = payload.decode("utf-8")
        return json.loads(
            text,
            object_pairs_hook=_json_reject_duplicates,
            parse_constant=_json_reject_constant,

        )
    except (UnicodeDecodeError, ValueError):
        return _JSON_MISSING


def _json_pointer_resolve(document: Any, tokens: tuple[str, ...]) -> Any:
    """Resolve parsed pointer tokens against an already-parsed document.

    Same traversal rules as :func:`_json_scalar_at`: a missing
    member/element, traversal through a non-container, an array token
    that is non-numeric (``-`` included), has leading zeroes or is
    out of range, or an addressed object/array rather than a scalar
    yields ``_JSON_MISSING``.
    """
    current = document
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                return _JSON_MISSING
            current = current[token]
        elif isinstance(current, list):
            # "-" addresses the nonexistent append position; array tokens
            # are plain decimal indices with no leading zeroes (RFC 6901).
            if (
                not token
                or token == "-"
                or any(char not in "0123456789" for char in token)
                or (len(token) > 1 and token[0] == "0")
            ):
                return _JSON_MISSING
            index = int(token)
            if index >= len(current):
                return _JSON_MISSING
            current = current[index]
        else:
            return _JSON_MISSING
    if current is None or isinstance(current, (str, bool, int, float)):
        return current
    return _JSON_MISSING


def _json_pointer_exists(document: Any, tokens: tuple[str, ...]) -> bool:
    """Whether parsed pointer tokens resolve to any value in a document.

    Same traversal rules as :func:`_json_pointer_resolve` — a missing
    member/element, traversal through a non-container, or an array token
    that is non-numeric (``-`` included), has leading zeroes or is out of
    range does not hit — but the addressed value may be anything: null, a
    scalar, an object or an array all count as present, and the empty
    token tuple addresses the whole document.
    """
    current = document
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                return False
            current = current[token]
        elif isinstance(current, list):
            # "-" addresses the nonexistent append position; array tokens
            # are plain decimal indices with no leading zeroes (RFC 6901).
            if (
                not token
                or token == "-"
                or any(char not in "0123456789" for char in token)
                or (len(token) > 1 and token[0] == "0")
            ):
                return False
            index = int(token)
            if index >= len(current):
                return False
            current = current[index]
        else:
            return False
    return True


def _json_pointer_value(document: Any, tokens: tuple[str, ...]) -> Any:
    """Resolve parsed pointer tokens to the addressed value of any type.

    Same traversal rules as :func:`_json_pointer_exists` — a missing
    member/element, traversal through a non-container, or an array token
    that is non-numeric (``-`` included), has leading zeroes or is out of
    range yields the ``_JSON_MISSING`` sentinel — but the addressed value
    itself is returned whatever it is: null, a scalar, an object or an
    array, and the empty token tuple addresses the whole document.
    """
    current = document
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                return _JSON_MISSING
            current = current[token]
        elif isinstance(current, list):
            # "-" addresses the nonexistent append position; array tokens
            # are plain decimal indices with no leading zeroes (RFC 6901).
            if (
                not token
                or token == "-"
                or any(char not in "0123456789" for char in token)
                or (len(token) > 1 and token[0] == "0")
            ):
                return _JSON_MISSING
            index = int(token)
            if index >= len(current):
                return _JSON_MISSING
            current = current[index]
        else:
            return _JSON_MISSING
    return current


def _json_type_kind_of(value: Any) -> str:
    """The find_where "type" kind name of an addressed JSON value.

    Booleans are checked before integers (``bool`` subclasses ``int``) and
    are never numbers; integers and floats are both "number" — the strict
    parse already rejected every non-finite float.
    """
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "array"
    return "object"

